<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,Contact,SafeHtml,GoogleCalendar,Connections};
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Hash,Http,Crypt,Storage};
use Illuminate\Http\UploadedFile;
final class OperationsTest extends TestCase {
 private string $privatePath;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void {parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');$this->privatePath=storage_path('framework/nov7-'.bin2hex(random_bytes(8)));config(['integrations.path'=>$this->privatePath,'operator.connections_path'=>$this->privatePath.'-platform','raero.admin_password_hash'=>Hash::make('test-password-123')]);Artisan::call('migrate',['--force'=>true]);foreach(['calendar_tasks','calendar_connections','media_assets','mail_templates','platform_settings','salon_state','deliveries','guest_accounts','providers'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);Http::preventStrayRequests();}
 protected function tearDown():void{foreach(glob($this->privatePath.'*') as $p)unlink($p);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('t',40)])->withHeader('X-CSRF-TOKEN',str_repeat('t',40));}
 private function booking(array $v=[]):array{return array_replace(['name'=>'Teszt','phone'=>'+36 30 123-4567','email'=>'guest@example.com','services'=>['cut'],'staff'=>'anna','start'=>'2035-03-12T09:00:00Z'],$v);}
 private function past():string{$this->admin();$b=$this->postJson('/api/bookings',$this->booking())->assertCreated()->json();app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']=now()->subHours(2)->utc()->toISOString();$s['bookings'][0]['status']='confirmed';});return $b['id'];}
 private function connection(string $owner='staff',string $id='anna',int $provider=1,array $extra=[]):int{return DB::table('calendar_connections')->insertGetId(array_replace(['owner_type'=>$owner,'owner_id'=>$id,'provider_id'=>$provider,'credentials'=>Crypt::encryptString(json_encode(['access_token'=>'test-access','refresh_token'=>'test-refresh','expires'=>time()+3600])),'calendar_id'=>'primary','enabled'=>true,'last_attempt_at'=>now(),'created_at'=>now(),'updated_at'=>now()],$extra));}
 public function test_no_show_is_timed_optional_and_never_creates_a_payment():void{$this->admin();$future=$this->postJson('/api/bookings',$this->booking())->assertCreated()->json();$this->patchJson('/api/bookings/'.$future['id'],['status'=>'no_show'])->assertUnprocessable();app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']=now()->subHours(2)->utc()->toISOString();$s['bookings'][0]['status']='confirmed';});$this->patchJson('/api/bookings/'.$future['id'],['attendance'=>'no_show','noShowFee'=>3000])->assertOk()->assertJsonPath('status','no_show')->assertJsonPath('noShowFee',3000);$s=app(SalonStore::class)->read();$this->assertCount(0,$s['payments']);$this->assertSame(3000,\App\Services\Offers::total($s['bookings'][0]));$this->postJson('/api/payments',['bookingId'=>$future['id'],'amount'=>3001,'method'=>'cash','paidAt'=>now()->toISOString()])->assertUnprocessable();$this->postJson('/api/payments',['bookingId'=>$future['id'],'amount'=>3000,'method'=>'cash','paidAt'=>now()->toISOString()])->assertCreated();$this->postJson('/api/payments',['bookingId'=>$future['id'],'amount'=>1,'method'=>'cash','paidAt'=>now()->toISOString()])->assertUnprocessable();}
 public function test_no_show_without_fee_keeps_final_attendance_and_pass_accounting():void{$id=$this->past();$this->patchJson('/api/bookings/'.$id,['attendance'=>'no_show','noShowFee'=>0])->assertOk();$this->patchJson('/api/bookings/'.$id,['attendance'=>'attended'])->assertUnprocessable();}
 public function test_contact_validation_normalization_and_formatting():void{foreach(['+36 30 123-4567','0036301234567','30 123 4567','06301234567'] as $v)$this->assertSame('06301234567',Contact::phone($v));$this->assertSame('06 30 123 4567',Contact::display('+36301234567'));$this->assertSame('+36301234567',Contact::e164('06301234567'));$this->assertSame('+442012345678',Contact::phone('+44 20 1234 5678'));$this->postJson('/api/bookings',$this->booking(['phone'=>'123']))->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['email'=>'invalid']))->assertUnprocessable();$this->postJson('/api/bookings',$this->booking())->assertCreated()->assertJsonPath('phone','06301234567');}
 public function test_hourly_public_slots_and_direct_api_enforce_the_same_grid():void{$this->admin();$this->putJson('/api/config',['settings'=>array_replace(app(SalonStore::class)->read()['settings'],['slotStep'=>60])])->assertOk();$slots=$this->getJson('/api/slots?date=2035-03-12&services=cut&staff=anna')->assertOk()->json();$this->assertNotEmpty($slots);foreach($slots as $slot)$this->assertStringEndsWith(':00',$slot['time']);$this->withSession(['admin'=>false]);$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-12T09:10:00Z']))->assertUnprocessable();$this->postJson('/api/bookings',$this->booking())->assertCreated();}
 public function test_provider_cannot_read_or_write_central_secrets_or_templates():void{$this->admin();$this->putJson('/api/connections',['smtp_host'=>'example.invalid'])->assertForbidden();$this->withSession(['platform_admin'=>true]);$this->putJson('/api/platform/connections',['google_client_id'=>'test-client','google_client_secret'=>'private-google','smtp_host'=>'example.invalid','mail_from'=>'sender@example.com'])->assertOk();$this->getJson('/api/platform/connections')->assertJsonPath('google_client_secret_configured',true)->assertJsonMissingPath('google_client_secret');$this->assertStringNotContainsString('private-google',file_get_contents($this->privatePath.'-platform'));$this->withSession(['platform_admin'=>false]);$this->getJson('/api/connections')->assertJsonMissingPath('smtp_host')->assertJsonMissingPath('google_client_secret_configured');$this->getJson('/api/platform/templates')->assertUnauthorized();}
 public function test_rich_text_and_html_template_variables_cannot_execute_code():void{$dirty='<p onclick="evil()">Szia <strong>név</strong><a href="javascript:evil()">link</a><img src=x onerror=evil()><script>evil()</script></p>';$safe=SafeHtml::clean($dirty);$this->assertStringContainsString('<strong>név</strong>',$safe);foreach(['onclick','javascript','onerror','<script','<img'] as $bad)$this->assertStringNotContainsString($bad,$safe);$this->admin();$this->withSession(['platform_admin'=>true]);$this->putJson('/api/platform/templates',['event'=>'created','subject'=>'Szia {{name}}','html'=>'<p>{{name}}</p><a href="{{manage_url}}">Foglalás</a>'.$dirty,'enabled'=>true])->assertOk();$r=app(\App\Services\MailTemplates::class)->render('created',['name'=>'<script>evil()</script>','manage_url'=>'https://example.com/fiokom']);$this->assertStringNotContainsString('<script>',$r['html']);$this->assertStringContainsString('href="https://example.com/fiokom"',$r['html']);}
 public function test_media_is_real_image_scoped_and_only_attached_images_are_public():void{Storage::fake('local');$this->admin();$file=UploadedFile::fake()->createWithContent('test.png',base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j1ioAAAAASUVORK5CYII='));$r=$this->post('/api/media',['target'=>'service','entityId'=>'cut','image'=>$file],['Accept'=>'application/json'])->assertCreated();$url=$r->json('url');$this->get(parse_url($url,PHP_URL_PATH))->assertOk();$this->assertSame($url,app(SalonStore::class)->read()['services'][0]['image']);$this->withSession(['provider_id'=>2]);$this->post('/api/media?provider=1',['target'=>'logo','image'=>$file],['Accept'=>'application/json'])->assertForbidden();$this->withSession(['provider_id'=>1]);app(SalonStore::class)->mutate(function(&$s){$s['services'][0]['image']='';});$this->get(parse_url($url,PHP_URL_PATH))->assertNotFound();}
 public function test_exports_are_real_excel_text_cells_and_private_calendar():void{$this->admin();$this->postJson('/api/bookings',$this->booking(['name'=>'=HYPERLINK("evil")']))->assertCreated();$r=$this->get('/api/exports/calendar?from=2035-03-01&to=2035-03-31&format=xlsx')->assertOk();$file=$r->baseResponse->getFile()->getPathname();$zip=new \PharData($file);$xml=$zip['xl/worksheets/sheet1.xml']->getContent();$this->assertStringContainsString('t="inlineStr"',$xml);$this->assertStringContainsString('=HYPERLINK',$xml);$this->assertStringNotContainsString('<f>',$xml);unset($zip);unlink($file);$this->get('/api/exports/calendar?from=2035-03-01&to=2035-03-31&format=ics')->assertOk()->assertSee('BEGIN:VCALENDAR',false)->assertDontSee('token',false);$this->withSession(['admin'=>false]);$this->get('/api/exports/statistics?from=2035-03-01&to=2035-03-31')->assertForbidden();}
 public function test_google_outbox_is_idempotent_and_disabled_connections_do_not_sync():void{$id=$this->connection();$this->admin();$this->postJson('/api/bookings',$this->booking())->assertCreated();$this->assertSame(1,DB::table('calendar_tasks')->count());$task=DB::table('calendar_tasks')->first();Http::fake(['www.googleapis.com/*'=>fn($r)=>Http::response([], $r->method()==='GET'?404:200)]);$result=app(GoogleCalendar::class)->run(5);$this->assertSame(1,$result['synced']);$this->assertSame('synced',DB::table('calendar_tasks')->value('status'));$requests=Http::recorded();$post=$requests->first(fn($x)=>$x[0]->method()==='POST')[0];$this->assertMatchesRegularExpression('/^raero[a-f0-9]{48}$/',$post['id']);$this->assertArrayNotHasKey('attendees',$post->data());$this->patchJson('/api/calendar/connection?owner=staff&staff=anna',['enabled'=>false])->assertOk();$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-13T09:00:00Z']))->assertCreated();$this->assertSame(1,DB::table('calendar_tasks')->count());$this->getJson('/api/calendar/connection?owner=staff&staff=anna')->assertOk()->assertJsonMissingPath('credentials')->assertJsonPath('enabled',false);}
 public function test_cached_google_busy_is_scoped_and_prevents_conflicting_booking():void{$from=strtotime('2035-03-12T09:00:00Z');$this->connection('staff','anna',1,['busy'=>json_encode([['start'=>$from,'end'=>$from+3600]])]);$this->connection('staff','eszter',2,['busy'=>json_encode([['start'=>$from,'end'=>$from+86400]])]);$this->postJson('/api/bookings',$this->booking())->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['staff'=>'eszter','services'=>['massage']]))->assertCreated();Http::assertNothingSent();}
 public function test_google_busy_import_ignores_own_events_and_private_event_details():void{$id=$this->connection();$c=DB::table('calendar_connections')->find($id);Http::fake(['www.googleapis.com/*'=>Http::response(['items'=>[['summary'=>'Private title','start'=>['dateTime'=>'2035-03-12T09:00:00Z'],'end'=>['dateTime'=>'2035-03-12T10:00:00Z']],['start'=>['dateTime'=>'2035-03-12T11:00:00Z'],'end'=>['dateTime'=>'2035-03-12T12:00:00Z'],'extendedProperties'=>['private'=>['raero_provider'=>'1','raero_booking'=>'ours']]]]])]);app(GoogleCalendar::class)->pullBusy($c);$row=DB::table('calendar_connections')->find($id);$this->assertCount(1,json_decode($row->busy,true));$this->assertStringNotContainsString('Private title',$row->busy);$this->assertNotNull($row->last_synced_at);}
 public function test_calendar_owner_permissions_and_oauth_state_are_checked():void{$this->connection();$this->admin();$this->getJson('/api/calendar/connection?owner=staff&staff=anna&provider=2')->assertForbidden();$this->getJson('/api/calendar/connection?owner=staff&staff=missing')->assertNotFound();$this->get('/auth/google-calendar/callback?state=wrong&code=bad')->assertRedirect('/fiokom?calendarError=state');Http::assertNothingSent();}
 public function test_google_calendar_consent_is_separate_and_refresh_tokens_remain_private():void{
  app(Connections::class)->save(['google_client_id'=>'test-client','google_client_secret'=>'test-secret']);$this->admin();
  $r=$this->get('/auth/google-calendar?owner=staff&staff=anna');$r->assertRedirect();parse_str(parse_url($r->headers->get('Location'),PHP_URL_QUERY),$q);$this->assertStringContainsString('calendar.events',$q['scope']);$this->assertSame('offline',$q['access_type']);$this->assertSame('S256',$q['code_challenge_method']);
  Http::fake(['oauth2.googleapis.com/token'=>Http::response(['access_token'=>'new-access','refresh_token'=>'private-refresh','expires_in'=>3600]),'openidconnect.googleapis.com/*'=>Http::response(['sub'=>'person','email'=>'owner@example.com']),'www.googleapis.com/*'=>Http::response(['items'=>[]])]);
  $this->get('/auth/google-calendar/callback?state='.$q['state'].'&code=code')->assertRedirect('/?provider=1&calendarSettings=1&calendarConnected=1');$row=DB::table('calendar_connections')->first();$this->assertStringNotContainsString('private-refresh',$row->credentials);$this->getJson('/api/calendar/connection?owner=staff&staff=anna')->assertOk()->assertJsonPath('email','owner@example.com')->assertJsonMissingPath('credentials');
  $this->deleteJson('/api/calendar/connection?owner=staff&staff=anna')->assertOk();$this->assertSame(0,DB::table('calendar_connections')->count());
 }
 public function test_google_failure_is_not_reported_as_success_and_retry_does_not_duplicate():void{
  $id=$this->connection('staff','anna',1,['last_attempt_at'=>null]);$this->admin();$this->postJson('/api/bookings',$this->booking())->assertCreated();Http::fake(['www.googleapis.com/*'=>Http::response([],403)]);$result=app(GoogleCalendar::class)->run(1);$this->assertSame(0,$result['synced']);$this->assertNotNull(DB::table('calendar_connections')->where('id',$id)->value('last_error'));$this->assertNull(DB::table('calendar_connections')->where('id',$id)->value('last_synced_at'));$this->assertSame('pending',DB::table('calendar_tasks')->value('status'));$this->patchJson('/api/calendar/connection?owner=staff&staff=anna',['enabled'=>true])->assertOk();$this->assertSame(1,DB::table('calendar_tasks')->count());
 }
 public function test_statistics_export_contains_all_four_excel_sheets_and_real_payments():void{
  $id=$this->past();$this->postJson('/api/payments',['bookingId'=>$id,'amount'=>2000,'method'=>'cash','paidAt'=>now()->toISOString()])->assertCreated();$r=$this->get('/api/exports/statistics?from='.now()->subDay()->format('Y-m-d').'&to='.now()->format('Y-m-d'))->assertOk();$file=$r->baseResponse->getFile()->getPathname();$zip=new \PharData($file);$this->assertStringContainsString('Befizetések',$zip['xl/workbook.xml']->getContent());$this->assertStringContainsString('<v>2000</v>',$zip['xl/worksheets/sheet4.xml']->getContent());unset($zip);unlink($file);
 }

 public function test_legacy_registered_phone_can_be_canonicalized_without_changing_ownership():void{\App\Services\Clients::editable(['guestId'=>10,'phone'=>'+36 30 123-4567','email'=>'guest@example.com'],['phone'=>'06301234567','email'=>'guest@example.com']);$this->addToAssertionCount(1);$this->expectException(\InvalidArgumentException::class);\App\Services\Clients::editable(['guestId'=>10,'phone'=>'+36301234567'],['phone'=>'06309998888']);}

 public function test_private_operator_import_exposes_only_transfer_fields_to_provider():void{$data=['name'=>'Minta Üzemeltető','country'=>'Magyarország','zip'=>'0000','city'=>'Minta város','address'=>'Privát minta cím','taxNumber'=>'00000000-0-00','registrationNumber'=>'00000000','bank'=>'Minta Bank','account'=>'00000000-00000000-00000000','iban'=>'HU00000000000000000000000000','bic'=>'TESTHU00'];$file=$this->privatePath.'-operator.json';file_put_contents($file,json_encode($data));$this->assertSame(0,Artisan::call('raero:operator-import',['file'=>$file]));$this->admin();$this->getJson('/api/subscription/info')->assertOk()->assertJsonPath('operator.name','Minta Üzemeltető')->assertJsonPath('operator.account',$data['account'])->assertJsonMissingPath('operator.address')->assertJsonMissingPath('operator.taxNumber');}

 private function serviceMode(string $mode,int $capacity=2):void{app(SalonStore::class)->mutate(function(&$s)use($mode,$capacity){$s['settings']['advancedBookingEnabled']=true;$s['services'][0]['bookingMode']=$mode;$s['services'][0]['capacity']=$capacity;});}
 private function groupFixture(int $capacity=2,string $start='2035-03-12T09:00:00Z'):array{$this->admin();$this->serviceMode('group',$capacity);return $this->postJson('/api/group-sessions',['serviceId'=>'cut','staff'=>'anna','start'=>$start,'capacity'=>$capacity])->assertCreated()->json();}
 public function test_default_service_applies_only_to_provider_bookings():void{$this->admin();app(SalonStore::class)->mutate(function(&$s){$s['settings']['defaultServiceId']='cut';});$v=$this->booking();unset($v['services']);$this->postJson('/api/bookings',$v)->assertCreated()->assertJsonPath('services.0','cut');$this->withSession(['admin'=>false]);$this->postJson('/api/bookings',$v)->assertUnprocessable();}
 public function test_unnamed_booking_needs_consent_and_creates_no_fake_contact():void{$this->admin();$v=$this->booking(['name'=>'','email'=>'','phone'=>'']);$this->postJson('/api/bookings',$v)->assertUnprocessable();$this->postJson('/api/bookings',$v+['allowUnnamed'=>true,'rememberUnnamed'=>true])->assertCreated()->assertJsonPath('name','Név nélküli vendég')->assertJsonPath('anonymous',true);$s=app(SalonStore::class)->read();$this->assertCount(0,$s['clients']);$this->assertTrue($s['settings']['skipUnnamedWarning']);$this->postJson('/api/bookings',array_replace($v,['start'=>'2035-03-13T09:00:00Z']))->assertCreated();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['skipUnnamedWarning'=>false])])->assertOk();$this->postJson('/api/bookings',array_replace($v,['start'=>'2035-03-14T09:00:00Z']))->assertUnprocessable();$this->withSession(['admin'=>false]);$this->postJson('/api/bookings',$v+['allowUnnamed'=>true])->assertUnprocessable();}
 public function test_parallel_capacity_rejects_third_and_different_active_service():void{$this->admin();$this->serviceMode('parallel',2);$this->postJson('/api/bookings',$this->booking())->assertCreated();$this->postJson('/api/bookings',$this->booking())->assertCreated();$this->postJson('/api/bookings',$this->booking())->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['services'=>['color']]))->assertUnprocessable();}
 public function test_parallel_capacity_counts_simultaneous_people_not_all_overlapping_visits():void{$this->admin();$this->serviceMode('parallel',2);foreach(['09:00','09:45'] as $t)$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-12T'.$t.':00Z']))->assertCreated();app(SalonStore::class)->mutate(function(&$s){$s['services'][0]['duration']=90;});$this->postJson('/api/bookings',$this->booking())->assertCreated();}
 public function test_processing_time_still_allows_only_one_other_active_guest():void{$this->admin();app(SalonStore::class)->mutate(function(&$s){$s['services'][0]['duration']=10;});$this->postJson('/api/bookings',$this->booking(['services'=>['color']]))->assertCreated();$v=$this->booking(['start'=>'2035-03-12T09:30:00Z']);$this->postJson('/api/bookings',$v)->assertCreated();$this->postJson('/api/bookings',$v)->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-12T09:40:00Z']))->assertCreated();}
 public function test_group_class_reserves_worker_even_when_empty_and_rejects_arbitrary_starts():void{$g=$this->groupFixture();$this->postJson('/api/bookings',$this->booking(['services'=>['color']]))->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-12T09:10:00Z']))->assertUnprocessable();$this->postJson('/api/bookings',$this->booking(['services'=>['cut','color']]))->assertUnprocessable();$this->getJson('/api/public')->assertJsonPath('groupSessions.0.remaining',2)->assertJsonMissingPath('groupSessions.0.bookings');}
 public function test_group_seats_limits_resize_and_whole_class_cancellation():void{$g=$this->groupFixture();for($i=0;$i<2;$i++)$this->postJson('/api/bookings',$this->booking())->assertCreated()->assertJsonPath('groupSessionId',$g['id']);$this->postJson('/api/bookings',$this->booking())->assertUnprocessable();$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>1])->assertUnprocessable();$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3])->assertCreated();$this->postJson('/api/bookings',$this->booking())->assertCreated();$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>3,'cancelled'=>true])->assertCreated();foreach(app(SalonStore::class)->read()['bookings'] as $b)$this->assertSame('cancelled',$b['status']);$this->getJson('/api/public')->assertJsonCount(0,'groupSessions');}
 public function test_group_slots_are_only_published_starts_with_available_seats():void{$g=$this->groupFixture(2,'2035-03-12T09:15:00Z');$this->withSession(['admin'=>false]);$slots=$this->getJson('/api/slots?date=2035-03-12&services=cut&staff=anna')->assertOk()->json();$this->assertCount(1,$slots);$this->assertSame('10:15',$slots[0]['time']);$this->postJson('/api/bookings',$this->booking(['start'=>$g['start']]))->assertCreated();$this->getJson('/api/slots?date=2035-03-12&services=cut&staff=anna')->assertJsonPath('0.remaining',1);}
 public function test_calendar_offer_is_guest_owned_once_and_salon_cannot_connect_a_customer():void{app(Connections::class)->save(['google_client_id'=>'client','google_client_secret'=>'secret']);DB::table('guest_accounts')->insert(['id'=>42,'name'=>'Vendég','provider'=>'google','subject'=>'42','email'=>'guest@example.com','created_at'=>now(),'updated_at'=>now()]);$this->withSession(['guest_id'=>42,'admin'=>false]);$this->getJson('/api/guest/calendar-prompt')->assertOk()->assertJsonPath('offer',true);$this->postJson('/api/guest/calendar-prompt')->assertOk();$this->getJson('/api/guest/calendar-prompt')->assertJsonPath('offer',false);$this->admin();$this->getJson('/api/calendar/connection?owner=guest&guestId=42')->assertForbidden();$this->get('/auth/google-calendar?owner=guest&guestId=42')->assertForbidden();$this->getJson('/api/guest/calendar-prompt')->assertForbidden();}
 public function test_group_management_is_provider_scoped_and_public_cannot_publish():void{$this->withSession(['admin'=>false]);$this->postJson('/api/group-sessions',['capacity'=>2])->assertForbidden();$this->admin();$this->getJson('/api/group-sessions?provider=2')->assertForbidden();}

 public function test_guest_reschedule_transfers_group_seat_to_new_class():void{$a=$this->groupFixture();$b=$this->postJson('/api/group-sessions',['serviceId'=>'cut','staff'=>'anna','start'=>'2035-03-13T09:00:00Z','capacity'=>2])->assertCreated()->json();$this->withSession(['admin'=>false]);$booking=$this->postJson('/api/bookings',$this->booking())->assertCreated()->json();$this->patchJson('/api/manage',['token'=>$booking['token'],'start'=>$b['start']])->assertOk();$state=app(SalonStore::class)->read();$this->assertSame($b['id'],$state['bookings'][0]['groupSessionId']);$this->assertSame(0,\App\Services\GroupSessions::booked($a,$state));$this->assertSame(1,\App\Services\GroupSessions::booked($b,$state));}
 public function test_published_class_prevents_archiving_or_repricing_its_resources():void{$g=$this->groupFixture();$s=app(SalonStore::class)->read();$services=$s['services'];$services[0]['price']+=100;$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();$this->deleteJson('/api/staff/anna')->assertUnprocessable();$this->postJson('/api/group-sessions',['id'=>$g['id'],'capacity'=>2,'cancelled'=>true])->assertCreated();$this->putJson('/api/config',['services'=>$services])->assertOk();}

 public function test_anonymous_and_group_booking_csv_records_keep_their_constraints():void{$this->admin();$a=$this->postJson('/api/bookings',$this->booking(['name'=>'','phone'=>'','email'=>'','allowUnnamed'=>true]))->assertCreated()->json();$this->postJson('/api/imports/bookings',['records'=>[$a]])->assertOk();$this->assertCount(0,app(SalonStore::class)->read()['clients']);$g=$this->groupFixture(1,'2035-03-13T09:00:00Z');$b=$this->postJson('/api/bookings',$this->booking(['start'=>$g['start']]))->assertCreated()->json();$this->postJson('/api/imports/bookings',['records'=>[$b]])->assertOk();$b['id']='other-import';$b['serviceSnapshot'][0]['capacity']=100;$this->postJson('/api/imports/bookings',['records'=>[$b]])->assertUnprocessable();}

 public function test_footer_import_publishes_only_explicit_public_contact_configuration():void{$file=$this->privatePath.'-footer.json';file_put_contents($file,json_encode(['name'=>'Minta Üzemeltető','email'=>'contact@example.invalid','phone'=>'06301234567','address'=>'Minta utca 1.','taxNumber'=>'00000000-0-00','website'=>'https://example.com','contactUrl'=>'https://example.com/contact','smtp_password'=>'must-not-be-public']));$this->assertSame(0,Artisan::call('raero:footer-import',['file'=>$file]));$this->getJson('/api/public')->assertOk()->assertJsonMissingPath('publicFooter');$this->assertNull(DB::table('platform_settings')->where('id',1)->first());}

}
